import { FloodState } from "../components/FloodState.js";
import { Position } from "../components/Position.js";
import { TILE_FLOOR, TILE_SHALLOW_WATER } from "../environment/dungeon/constants.js";
import { getTile, setTile } from "../environment/dungeon/tileMap.js";

const CARDINALS = Object.freeze([
  Object.freeze({ dx: 0, dy: -1 }),
  Object.freeze({ dx: 1, dy: 0 }),
  Object.freeze({ dx: 0, dy: 1 }),
  Object.freeze({ dx: -1, dy: 0 }),
]);

function tileKey(x, y) {
  return `${x | 0},${y | 0}`;
}

/**
 * Expand active floods one deterministic layer per world step.
 * Water occupies floor tiles only and remains shallow/walkable.
 */
export function floodSystem(world) {
  for (const [id, pos, state] of world.query(Position, FloodState)) {
    const flooded = new Set(state.floodedTiles.map((tile) => tileKey(tile.x, tile.y)));
    const nextFrontier = [];
    let remaining = state.remainingVolume | 0;

    for (const tile of state.frontier) {
      if (remaining <= 0 || nextFrontier.length >= state.spreadPerTurn) break;
      for (const dir of CARDINALS) {
        if (remaining <= 0 || nextFrontier.length >= state.spreadPerTurn) break;
        const x = (tile.x | 0) + dir.dx;
        const y = (tile.y | 0) + dir.dy;
        const key = tileKey(x, y);
        if (flooded.has(key) || getTile(x, y) !== TILE_FLOOR) continue;
        setTile(x, y, TILE_SHALLOW_WATER);
        flooded.add(key);
        nextFrontier.push({ x, y });
        remaining--;
      }
    }

    const turnsLeft = Math.max(0, (state.turnsLeft | 0) - 1);
    if (remaining <= 0 || turnsLeft <= 0 || nextFrontier.length === 0) {
      world.remove(id, FloodState);
      continue;
    }

    world.set(id, FloodState, {
      ...state,
      remainingVolume: remaining,
      turnsLeft,
      frontier: nextFrontier,
      floodedTiles: Array.from(flooded, (key) => {
        const [x, y] = key.split(",").map(Number);
        return { x, y };
      }),
    });
  }
}

export function startFlood(world, sourceId, params = {}) {
  const pos = world.get(sourceId, Position);
  if (!pos) return false;
  const volume = Math.max(1, Number(params.volume ?? 18) | 0);
  const spreadPerTurn = Math.max(1, Number(params.spreadPerTurn ?? 3) | 0);
  const turns = Math.max(1, Number(params.turns ?? 8) | 0);
  const x = pos.x | 0;
  const y = pos.y | 0;
  const floodedTiles = [];
  if (getTile(x, y) === TILE_FLOOR) {
    setTile(x, y, TILE_SHALLOW_WATER);
    floodedTiles.push({ x, y });
  }
  world.add(sourceId, FloodState, {
    remainingVolume: Math.max(0, volume - floodedTiles.length),
    spreadPerTurn,
    turnsLeft: turns,
    frontier: [{ x, y }],
    floodedTiles,
  });
  return true;
}

